export const COLORS={free:'#43b99b',light:'#8dc85d',medium:'#f1b33c',crowded:'#f27837',very_crowded:'#ed5a61',unknown:'#68717d',no_service:'#ac7cf0'};
export function band(load){if(load===null)return'unknown';if(!Number.isFinite(load)||load<0)throw Error('Invalid load');return load<=40?'free':load<50?'light':load<60?'medium':load<70?'crowded':'very_crowded'}
export function plan(flows,trips,target=40){if(!flows.length||flows.some(v=>!Number.isFinite(v)||v<0)||!Number.isInteger(trips)||trips<0||!Number.isFinite(target)||target<=0)throw Error('Check service and demand inputs');const peak=Math.max(...flows),needed=Math.ceil(peak/target),load=trips?peak/trips:null;return{peak,needed,load,band:trips?band(load):'no_service',extra:Math.max(0,needed-trips),spare:Math.max(0,trips-Math.max(needed,1))}}
export function flowValues(route,day,hour){const values=route.profile[day]?.[String(hour)]||{};return route.sections.map(s=>values[s.id]||0)}
export function groundedExplanation(route,day,hour,trips,target=40){const p=plan(flowValues(route,day,hour),trips,target);const values=flowValues(route,day,hour),s=route.sections[values.indexOf(p.peak)];return`The historical ${day} profile estimates ${Math.round(p.peak)} passenger crossings on the busiest stage interval, ${s.from_name} to ${s.to_name}, at ${String(hour).padStart(2,'0')}:00.\n\n${trips?`Your assumption of ${trips} trips/hour gives ${p.load.toFixed(1)} passengers per bus (${p.band.replaceAll('_',' ')}).`:'No service is planned, so load per bus is undefined.'} At a target of ${target}, ${p.needed} trip passages/hour are required.\n\n${Math.round(route.missing_destination_share*100)}% of passenger records on this variant lack destinations. The calculation estimates their downstream travel; it does not observe actual crossing times or a verified timetable.`}
